Given a sorted array arr[] of n-1 integers, these integers are in the range of 1 to n. There are no duplicates in the array. One of the integers is missing in the array. Find the missing integer. Examples: Input : arr[] = [1, 2, 3, 4, 6, 7, 8]Output : 5Explanation: The missing integer in the above array is 5 Input : arr[] = [1, 2, 3, 4, 5, 6, 8, 9]Output : 7Explanation: The missing integer in the above array is 7 Try It YourselfTable of Content[Naive Approach] - Nested Loops - O(n^2) Time and O(1) Space[Better approach 1] - Comparing the difference between index and elements - O(n) Time and O(1) Space[Better approach 2] - Using Formula for Sum of n terms- O(n) Time and O(1) SpaceExpected Approach - Using Binary Search -  O(log(n)) Time and O(1) Space[Naive Approach] - Nested Loops - O(n^2) Time and O(1) SpaceThe idea is to use two nested loops, where the outer one iterate from 1 to n, and inner one iterate for each of the array arr[] elements, if the value in outer loop in not found in array arr[], return the value, else iterate to the next value.
            C++

    #include <iostream>
#include <vector>
using namespace std;

int missingNumber(vector<int> &arr) {
    int n = arr.size() + 1;

    // Iterate from 1 to n and check
    // if the current number is present
    for(int i = 1; i <= n; i++){
        bool found = false;
        for(int j = 0; j < n - 1; j++){
            if(arr[j] == i) {
                found = true;
                break;
            }
        }

        // If the current number is not present
        if(!found)
            return i;
    }
    return -1;
}

int main(){
    vector<int> arr = {1, 2, 3, 4, 6, 7, 8};
    cout << missingNumber(arr);
    return 0;
}


