Output5[Better approach 2] - Using Formula for Sum of n terms- O(n) Time and O(1) SpaceIn this approach we will create Function to find the missing number using the sum of natural numbers formula. First we will Calculate the total sum of the first N natural numbers using formula n * (n + 1) / 2. Now we calculate sum of all elements in given array. Subtract the total sum with sum of all elements in given array and return the missing number.
            C++

    #include <iostream>
#include <vector>

using namespace std;

int missingNumber(vector<int>& arr) {

    // Calculate the total sum
    int n = arr.size() + 1;
    int totalSum = n * (n + 1) / 2;

    // Calculate sum of all elements in the given array
    int arraySum = 0;
    for (int num : arr) {
        arraySum += num;
    }

    // Subtract  and return the total sum with the sum of
    // all elements in the array
    int missingNumber = totalSum - arraySum;

    return missingNumber;
}

int main()
{

    vector<int> arr = { 1, 2, 3, 4, 6, 7, 8 };
    cout << missingNumber(arr);

    return 0;
}


