            C++

    #include <iostream>
#include <vector>
using namespace std;

int missingNumber(vector<int> &arr) {
    int n = arr.size();

    // Extreme cases
    if (arr[0] != 1)
        return 1;
    if (arr[n - 1] != (n + 1))
        return n + 1;

    //implementing binary search
    int lo = 0, hi = n - 1;
    int mid;
    while ((hi - lo) > 1) {
        mid = (lo + hi) / 2;
        if ((arr[lo] - lo) != (arr[mid] - mid))
            hi = mid;
        else if ((arr[hi] - hi) != (arr[mid] - mid))
            lo = mid;
    }
    return (arr[lo] + 1);
}

int main() {
    vector<int> arr = { 1, 2, 3, 4, 6, 7, 8 };
    cout << missingNumber(arr);
}


